import cn from 'classnames';
import { AccordionProps, AccordionItem } from './accordion.types';

import './accordion.scss';
import { IdentificatorType } from '../../types/common';

// Per-item Tabs-shaped body support (additive, backlog #940). An item is
// rendered via TabItemsAccordionBody below instead of the legacy
// SimpleAccordionBody/GridAccordionBody path only when its ':itemsOrder'
// contains one of the component names below that GridAccordionBody never
// supported (teaser/table/embed-video/custom-component) — see
// hasTabItemsBody(). Existing 'image'/'text'-only items never match this
// check, so their rendering is untouched.
//
// TabItemsAccordionBody mirrors tabs.tsx's own ':items'/':itemsOrder'
// component switch verbatim (same JSX per component, including the
// custom-component slot) rather than importing it from tabs.tsx, so
// tabs.tsx itself — and its compiled markup — is not touched by this
// change.
import { TabComponents, TabImageItem, TabTextItem, TabItem } from '../tabs/tabs.types';
import { TableProps } from '../table/table.types';
import { TeaserProps } from '../teaser/teaser.types';
import Teaser from '../teaser/teaser';
import Table from '../table/table';
import EmbedVideo from '../embed-video/embed-video';
import { EmbedVideoProps } from '../embed-video/embed-video.type';

function SimpleAccordionBody({
  id,
  text,
  richText,
  className,
}: {
  id: IdentificatorType;
  text: string;
  richText: boolean;
  className?: string;
}) {
  return (
    <div className={cn('text', className)}>
      {richText ? (
        <div
          data-cmp-data-layer=""
          id={`text-${id.split('-')[1]}`}
          className="cmp-text"
          dangerouslySetInnerHTML={{ __html: text }}
        />
      ) : (
        <div data-cmp-data-layer="" id={`text-${id.split('-')[1]}`} className="cmp-text">
          <p>{text}</p>
        </div>
      )}
    </div>
  );
}

function GridAccordionBody({
  ':items': items,
  ':itemsOrder': itemsOrder,
  gridClassNames,
  columnClassNames,
}: AccordionItem) {
  return (
    <div className="responsivegrid">
      <div className={cn(gridClassNames)}>
        {items &&
          !!itemsOrder?.length &&
          itemsOrder.map((itemOrder, index) =>
            itemOrder === 'image' ? (
              <div key={index} className={cn('image', columnClassNames?.image)}>
                <div
                  data-asset-id={items.image.uuid}
                  id={items.image.id}
                  data-cmp-data-layer=""
                  className="cmp-image"
                  itemScope
                  itemType="http://schema.org/ImageObject"
                >
                  <img
                    srcSet={items.image.srcset}
                    loading="lazy"
                    className="cmp-image__image"
                    itemProp="contentUrl"
                    width="850"
                    height="509"
                    alt={items.image.title}
                    title={items.image.title}
                  />
                  <meta itemProp="caption" content={items.image.title} />
                </div>
              </div>
            ) : itemOrder === 'text' ? (
              <SimpleAccordionBody
                key={index}
                id={items.text.id}
                richText={items.text.richText}
                text={items.text.text}
                className={columnClassNames?.text}
              />
            ) : null,
          )}
      </div>
    </div>
  );
}

// Mirrors tabs.tsx's own per-item component switch (image/text/teaser/
// table/embed-video/custom-component), unchanged, so an accordion item
// using this shape renders exactly as the same item would inside Tabs.
function TabItemsAccordionBody({ ':items': items, ':itemsOrder': itemsOrder, columnClassNames }: TabItem) {
  return (
    <>
      {itemsOrder.map((componentName, index) => {
        const props = items[componentName];
        const componentClassName = columnClassNames[componentName];

        if (componentName === 'image') {
          const componentProps = props as TabImageItem;
          return (
            <div key={index} className={cn('image', componentClassName)}>
              <div
                data-asset-id={componentProps?.uuid}
                id={componentProps?.id}
                data-cmp-data-layer=""
                className="cmp-image"
                itemScope
                itemType="http://schema.org/ImageObject"
              >
                <img
                  srcSet={componentProps?.srcset}
                  loading="lazy"
                  className="cmp-image__image"
                  itemProp="contentUrl"
                  width="850"
                  height="509"
                  alt={componentProps?.title}
                  title={componentProps?.title}
                />
                <meta itemProp="caption" content={componentProps?.title} />
              </div>
            </div>
          );
        }
        if (componentName === 'text') {
          const componentProps = props as TabTextItem;
          return (
            <div key={index} className={cn('text', componentClassName)}>
              {componentProps?.richText ? (
                <div
                  data-cmp-data-layer=""
                  id={componentProps?.id}
                  className="cmp-text"
                  dangerouslySetInnerHTML={{ __html: componentProps?.text || '' }}
                />
              ) : (
                <div data-cmp-data-layer="" id={componentProps?.id} className="cmp-text">
                  <p>{componentProps?.text}</p>
                </div>
              )}
            </div>
          );
        }
        if (componentName === 'teaser') {
          const componentProps = props as TeaserProps;
          return (
            <Teaser key={index} {...componentProps} className={cn(componentProps.className, componentClassName)} />
          );
        }
        if (componentName === 'table') {
          const componentProps = props as TableProps;
          return (
            <Table key={index} {...componentProps} className={cn(componentProps.className, componentClassName)} />
          );
        }
        if (componentName === 'embed-video') {
          const componentProps = props as EmbedVideoProps;
          return (
            <EmbedVideo
              key={index}
              {...componentProps}
              className={cn(componentProps.className, componentClassName)}
            />
          );
        }
        if (componentName === 'custom-component') {
          return <>{props}</>;
        }
      })}
    </>
  );
}

// True only for items using the new Tabs-shaped body (teaser/table/
// embed-video/custom-component never appear in the legacy 'image'/'text'
// grid shape), so it never matches existing content.
const TAB_ONLY_COMPONENT_NAMES: TabComponents[] = ['teaser', 'table', 'embed-video', 'custom-component'];
function hasTabItemsBody(item: AccordionItem): boolean {
  return !!item[':itemsOrder']?.some((name) => (TAB_ONLY_COMPONENT_NAMES as string[]).includes(name));
}

export function Accordion({
  id,
  className,
  ':itemsOrder': itemsOrder,
  ':items': items,
  expandedItems,
  typeAccordion = 'default',
  onClick,
}: AccordionProps) {
  return (
    <div className={cn('accordion panelcontainer', className)}>
      <div id={id} className="cmp-accordion" data-cmp-data-layer="" data-placeholder-text="false">
        {!!itemsOrder?.length &&
          itemsOrder.map((itemOrder, index) => (
            <div
              key={index}
              className="cmp-accordion__item"
              data-cmp-hook-accordion="item"
              data-cmp-data-layer=""
              id={`${id}-item-${index}`}
              {...(expandedItems.includes(itemOrder) && { 'data-cmp-expanded': '' })}
            >
              <h3 className="cmp-accordion__header">
                <button
                  id={`${id}-item-${index}-button`}
                  className={cn('cmp-accordion__button', {
                    'cmp-accordion__button--expanded': expandedItems.includes(itemOrder),
                  })}
                  aria-controls={`${id}-item-${index}-panel`}
                  data-cmp-hook-accordion="button"
                  onClick={(e) => {
                    onClick && onClick(e, itemOrder);
                  }}
                >
                  <span className="cmp-accordion__title">{items[itemOrder]['cq:panelTitle']}</span>
                  <span className="cmp-accordion__icon"></span>
                </button>
              </h3>
              <div
                data-cmp-hook-accordion="panel"
                id={`${id}-item-${index}-panel`}
                className={cn(
                  'cmp-accordion__panel',
                  { 'cmp-accordion__panel--expanded': expandedItems.includes(itemOrder) },
                  { 'cmp-accordion__panel--hidden': !expandedItems.includes(itemOrder) },
                )}
                role="region"
                aria-labelledby={`${id}-item-${index}-button`}
                aria-hidden="false"
              >
                {hasTabItemsBody(items[itemOrder]) ? (
                  <TabItemsAccordionBody {...(items[itemOrder] as unknown as TabItem)} />
                ) : typeAccordion === 'default' ? (
                  <SimpleAccordionBody {...items[itemOrder]} />
                ) : (
                  <GridAccordionBody {...items[itemOrder]} />
                )}
              </div>
            </div>
          ))}
      </div>
    </div>
  );
}

export default Accordion;
